{"query": "
-- Update Andrew Adams title to CEO
UPDATE "Employee" SET "Title" = 'CEO' WHERE "EmployeeId" = 1;
-- Update Nancy Edwards phone
UPDATE "Employee" SET "Phone" = '+1 (403) 555-9999' WHERE "EmployeeId" = 2;
-- Rename IT Staff → IT Specialist
UPDATE "Employee" SET "Title" = 'IT Specialist' WHERE "Title" = 'IT Staff';
"}

{"query": "
-- Reassign customers 1,2,3 to Sarah Johnson (EmpId=9) and customers 4,5,6 to Mike Chen (EmpId=10)
UPDATE "Customer" SET "SupportRepId" = 9  WHERE "CustomerId" IN (1, 2, 3);
UPDATE "Customer" SET "SupportRepId" = 10 WHERE "CustomerId" IN (4, 5, 6);
"}

{"query": "
-- Change Sarah (9) and Mike (10) to report to Andrew Adams (EmployeeId=1)
UPDATE "Employee" SET "ReportsTo" = 1 WHERE "EmployeeId" IN (9, 10);
"}

{"query": "
-- Create the employee_performance table
CREATE TABLE IF NOT EXISTS employee_performance (
  employee_id       INTEGER PRIMARY KEY REFERENCES "Employee"("EmployeeId"),
  customers_assigned INTEGER,
  performance_score  DECIMAL
);
"}

{"query": "
-- Verify Robert's manager and any employees reporting to Robert
SELECT "EmployeeId", "FirstName", "LastName", "ReportsTo"
FROM "Employee"
WHERE "ReportsTo" = 7 OR "EmployeeId" = 7;
"}

{"query": "
-- Check customers assigned to Robert King (EmployeeId=7)
SELECT COUNT(*) AS customer_count FROM "Customer" WHERE "SupportRepId" = 7;
"}

{"query": "
-- No employees report to Robert (7), no customers assigned to him
-- Safely delete Robert King
DELETE FROM "Employee" WHERE "EmployeeId" = 7;
"}

{"query": "
-- Add salary column to Employee table
ALTER TABLE "Employee" ADD COLUMN IF NOT EXISTS "salary" DECIMAL;

-- Set all employees salary to 50000.00 first
UPDATE "Employee" SET "salary" = 50000.00;

-- Promote Laura Callahan and set her salary to 75000.00
UPDATE "Employee"
SET "Title" = 'Senior IT Specialist', "salary" = 75000.00
WHERE "EmployeeId" = 8;
"}
